inline bool range(const unsigned char* base,size_t imageSize,std::uint32_t offset,size_t length) {
 if(offset>=imageSize||length>imageSize-offset)return false;
 auto p=base+offset; auto end=p+length;
 while(p<end){
  MEMORY_BASIC_INFORMATION m{}; if(!VirtualQuery(p,&m,sizeof(m))||!m.RegionSize)return false;
  if(m.AllocationBase!=base||m.State!=MEM_COMMIT||(m.Protect&(PAGE_GUARD|PAGE_NOACCESS)))return false;
  if(!(m.Protect&(PAGE_EXECUTE_READ|PAGE_EXECUTE_READWRITE|PAGE_EXECUTE_WRITECOPY)))return false;
  auto next=static_cast<const unsigned char*>(m.BaseAddress)+m.RegionSize;
  if(next<=p)return false; p=std::min(next,end);
 }
 return true;
}
inline void* resolve(std::wstring& error){
 auto base=reinterpret_cast<unsigned char*>(GetModuleHandleW(nullptr));
 if(!base){error=L"game image unavailable";return nullptr;}
 auto dos=reinterpret_cast<IMAGE_DOS_HEADER*>(base);
 if(dos->e_magic!=IMAGE_DOS_SIGNATURE||dos->e_lfanew<=0||dos->e_lfanew>1048576){error=L"invalid image header";return nullptr;}
 auto nt=reinterpret_cast<IMAGE_NT_HEADERS64*>(base+dos->e_lfanew);
 if(nt->Signature!=IMAGE_NT_SIGNATURE||nt->FileHeader.Machine!=IMAGE_FILE_MACHINE_AMD64||nt->OptionalHeader.Magic!=IMAGE_NT_OPTIONAL_HDR64_MAGIC){error=L"invalid x64 image";return nullptr;}
 for(const auto& segment:segments){
  if(!range(base,nt->OptionalHeader.SizeOfImage,segment.rva,segment.size)||std::memcmp(base+segment.rva,segment.bytes,segment.size)){
   error=L"population code/call contract changed at RVA "+std::to_wstring(segment.rva);return nullptr;
  }
 }
 return base+segments[0].rva;
}
